from typing import List


def largestInteger(nums: List[int], k: int) -> int:
    from collections import defaultdict
    count = defaultdict(int)
    n = len(nums)

    # Count occurrences of each number in all subarrays of size k
    for i in range(n - k + 1):
        unique_numbers = set(nums[i:i + k])  # Unique numbers in the current subarray
        for num in unique_numbers:
            count[num] += 1

    # Find the largest number that appears in exactly one subarray
    largest = -1
    for num, cnt in count.items():
        if cnt == 1 and num > largest:
            largest = num

    return largest

