def totalNumbers(digits: List[int]) -> int:
    even_digits = [d for d in digits if d % 2 == 0]
    unique_numbers = set()
    for even_digit in even_digits:
        remaining_digits = digits.copy()
        remaining_digits.remove(even_digit)  # keep the even digit for the last position
        for first_digit in set(remaining_digits):
            if first_digit != 0:  # No leading zeros allowed
                for second_digit in remaining_digits:
                    for i in range(remaining_digits.count(first_digit)):
                        unique_numbers.add((first_digit, second_digit, even_digit))
    return len(unique_numbers)

