from typing import List


def longestSubsequence(nums: List[int]) -> int:
    n = len(nums)
    if n < 2:
        return n

    dp = [1] * n  # dp[i] will store the length of the longest subsequence ending at nums[i]
    max_length = 1

    # Start checking all pairs (i, j)
    for i in range(n):
        for j in range(i):
            diff1 = abs(nums[i] - nums[j])
            # Check all previous numbers to see if the difference condition holds
            valid = True
            for k in range(j):
                diff2 = abs(nums[j] - nums[k])
                if diff1 > diff2:
                    valid = False
                    break
            if valid:
                dp[i] = max(dp[i], dp[j] + 1)
        max_length = max(max_length, dp[i])

    return max_length

