def maxFreeTime(eventTime: int, k: int, startTime: List[int], endTime: List[int]) -> int:
    n = len(startTime)
    free_times = []
    last_end = 0

    # Collect all free time gaps
    sorted_meetings = [(startTime[i], endTime[i]) for i in range(n)]

    # Free time before the first meeting
    if sorted_meetings[0][0] > 0:
        free_times.append(sorted_meetings[0][0] - 0)

    # Free time between meetings
    for i in range(1, n):
        if sorted_meetings[i][0] > sorted_meetings[i - 1][1]:
            free_times.append(sorted_meetings[i][0] - sorted_meetings[i - 1][1])

    # Free time after the last meeting
    if sorted_meetings[-1][1] < eventTime:
        free_times.append(eventTime - sorted_meetings[-1][1])

    # Total free time without any rescheduling
    if k == 0:
        return max(free_times) if free_times else 0

    # Calculate max free time possible with rescheduling k meetings
    max_additional_free_time = 0
    for i in range(len(free_times)):  
        current_free_time = 0
        # Calculate the total potential free time by considering merging up to k free gaps
        for j in range(k + 1):
            if i + j < len(free_times):
                current_free_time += free_times[i + j]
        max_additional_free_time = max(max_additional_free_time, current_free_time)

    return max_additional_free_time

